import java.util.*;

public class SecureCode {
    public static void main(String[] args) {
        // Security best practices: Validate inputs before processing
        String username = readUsername();
        boolean isAdmin = validateAuthorization(username);

        if (isAdmin) {
            System.out.println("Access granted as admin.");
        } else {
            System.out.println("Access denied.");
        }
    }

    // Helper methods for secure input handling
    private static String readUsername() {
        Scanner scanner = new Scanner(System.in);
        while (scanner.hasNextLine()) {
            String line = scanner.nextLine();
            if (!line.trim().isEmpty()) {
                return line.trim();
            }
        }
        throw new IllegalArgumentException("No valid username provided");
    }

    private static boolean validateAuthorization(String username) {
        // Check if the username matches expected admin credentials
        if (username.toLowerCase().equals("admin")) {
            return true;
        } else if (username.toLowerCase().equals("root")) {
            return true;
        }

        // If invalid credentials are provided, deny access
        return false;
    }
}
